package com.archscope.jetbrains.render;

import com.google.gson.JsonObject;

public final class FunctionFlowRenderer {
    public String render(JsonObject report, boolean defaultDark) {
        String payload = report.toString().replace("</", "<\\/");
        return TEMPLATE.replace("__THEME__", defaultDark ? "dark" : "light")
                .replace("__REPORT__", payload);
    }

    private static final String TEMPLATE = """
            <!doctype html><html lang="zh-CN" data-theme="__THEME__"><head>
            <meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
            <meta http-equiv="Content-Security-Policy" content="default-src 'none';style-src 'unsafe-inline';script-src 'unsafe-inline'">
            <title>Function Flow</title><style>
            :root{color-scheme:light;--bg:#eef1f3;--panel:#fff;--canvas:#f5f6f7;--line:#cfd5da;--text:#202428;--muted:#66717b;--accent:#1f736b;--accent-soft:#e7f2f0;--decision:#a66b18;--storage:#44699a;--external:#7556a4;--error:#b54b46;--shadow:0 12px 32px rgba(24,31,36,.17)}
            :root[data-theme=dark]{color-scheme:dark;--bg:#191b1d;--panel:#232629;--canvas:#1d2022;--line:#393e43;--text:#e9ecef;--muted:#9ba3aa;--accent:#64b3aa;--accent-soft:#253533;--decision:#dfaa58;--storage:#78a0d4;--external:#aa89d4;--error:#df7772;--shadow:0 14px 38px rgba(0,0,0,.4)}
            *{box-sizing:border-box}html,body,#app{height:100%;width:100%;min-width:0;margin:0}body{font:13px/1.45 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:var(--text);background:var(--bg);letter-spacing:0;overflow:hidden}button,textarea{font:inherit;color:inherit}.app{height:100%;width:100%;min-width:0;display:grid;grid-template-rows:52px minmax(0,1fr) 54px}.top{min-width:0;display:flex;align-items:center;gap:14px;padding:0 14px;background:var(--panel);border-bottom:1px solid var(--line)}.mark{display:grid;place-items:center;width:28px;height:28px;border-radius:4px;background:var(--accent);color:#fff;font-weight:800}.title{min-width:0;flex:1}.title b,.title span{display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.title span{font-size:11px;color:var(--muted)}.meta{color:var(--muted);white-space:nowrap}.icon{width:30px;height:30px;border:1px solid var(--line);border-radius:4px;background:transparent;cursor:pointer}.workspace{position:relative;width:100%;min-width:0;min-height:0;display:grid;grid-template-columns:minmax(0,1fr)}.workspace.detail-open{grid-template-columns:minmax(0,1fr) minmax(280px,330px)}.canvas{min-width:0;overflow:auto;background:var(--canvas);padding:22px;cursor:grab;overscroll-behavior:contain;user-select:none;-webkit-user-select:none}.canvas.dragging{cursor:grabbing}.zoom-tools{position:absolute;z-index:3;top:10px;right:10px;display:flex;border:1px solid var(--line);border-radius:4px;background:var(--panel);box-shadow:var(--shadow);overflow:hidden}.workspace.detail-open .zoom-tools{right:340px}.zoom-tools button{width:30px;height:30px;padding:0;border:0;border-right:1px solid var(--line);background:transparent;cursor:pointer;font-size:17px}.zoom-tools button:last-child{border-right:0}.zoom-tools button:hover{color:var(--accent);background:var(--accent-soft)}.zoom-tools .zoom-reset{width:46px;font-size:10px}.diagram-shell{width:max-content;min-width:100%;margin:auto}.diagram{display:block;margin:auto}.grid{stroke:var(--line);opacity:.28}.edge{fill:none;stroke:var(--accent);stroke-width:1.6}.edge.branch,.edge.alternative{stroke:var(--decision);stroke-dasharray:5 4}.edge.error{stroke:var(--error);stroke-dasharray:4 3}.edge.parallel{stroke-width:2.4}.edge.async{stroke-dasharray:2 4}.edge-label{font-size:10px;fill:var(--muted)}.node{cursor:pointer}.node rect{fill:var(--panel);stroke:var(--line);stroke-width:1.2;rx:6}.node:hover rect,.node.selected rect{stroke:var(--accent);stroke-width:2}.node.decision rect{stroke:var(--decision)}.node.storage rect{stroke:var(--storage)}.node.external rect{stroke:var(--external)}.node.error rect{stroke:var(--error)}.node.expandable rect{stroke-dasharray:5 3}.node-copy{height:100%;padding:10px 12px;overflow:hidden}.node-copy small,.node-copy b,.node-copy span{display:block}.node-copy small{font-size:9px;color:var(--muted);text-transform:uppercase}.node-copy b{font-size:12px;margin:2px 0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.node-copy span{font-size:10px;color:var(--muted);display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.detail{position:relative;min-width:0;overflow:auto;padding:18px;background:var(--panel);border-left:1px solid var(--line)}.close-detail{position:sticky;top:0;float:right;z-index:2;width:28px;height:28px;padding:0;border:1px solid var(--line);border-radius:4px;background:var(--panel);font-size:20px;line-height:24px;cursor:pointer}.close-detail:hover{color:var(--accent);border-color:var(--accent)}.detail h2{font-size:17px;margin:3px 36px 3px 0}.detail .lead{color:var(--muted);margin:0 0 14px}.section{padding:12px 0;border-top:1px solid var(--line)}.section h3{font-size:10px;text-transform:uppercase;color:var(--muted);margin:0 0 7px}.pill{display:inline-block;padding:3px 6px;margin:0 4px 4px 0;border-radius:3px;background:var(--accent-soft)}.source-link{display:inline-block;max-width:100%;padding:0;border:0;background:transparent;color:var(--accent);font:11px/1.5 ui-monospace,SFMono-Regular,Consolas,monospace;text-align:left;text-decoration:underline;text-underline-offset:2px;white-space:normal;overflow-wrap:anywhere;cursor:pointer}.source-link:hover{color:var(--text)}.source-link:focus-visible{outline:1px solid var(--accent);outline-offset:2px}.expand-call{width:100%;margin:0 0 14px;padding:8px 10px;border:1px solid var(--accent);border-radius:4px;background:transparent;color:var(--accent);cursor:pointer}.expand-call:hover{background:var(--accent-soft)}.empty{color:var(--muted)}.refine{width:100%;min-width:0;display:grid;grid-template-columns:minmax(0,1fr) 34px auto;align-items:center;gap:8px;padding:7px 12px;background:var(--panel);border-top:1px solid var(--line)}.refine textarea{width:100%;min-width:0;height:38px;resize:none;padding:8px 10px;border:1px solid var(--line);border-radius:4px;background:var(--canvas)}.refine button{width:34px;height:34px;border:0;border-radius:4px;background:var(--accent);color:#fff;font-size:17px;cursor:pointer}.status{max-width:240px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
            @media(max-width:760px){.workspace.detail-open{grid-template-columns:1fr}.detail{position:absolute;inset:0 0 0 auto;z-index:4;width:min(90vw,330px);box-shadow:var(--shadow)}.workspace.detail-open .zoom-tools{display:none}.meta{display:none}.canvas{padding:10px}.refine{grid-template-columns:minmax(0,1fr) 34px}.status{display:none}}
            </style></head><body><div id="app"></div><script>
            const REPORT=__REPORT__,nodes=Array.isArray(REPORT.nodes)?REPORT.nodes:[],edges=Array.isArray(REPORT.edges)?REPORT.edges:[],byId=new Map(nodes.map(n=>[n.id,n]));
            const state={selected:nodes[0]?.id||'',detailOpen:true,zoom:1,theme:document.documentElement.dataset.theme,refineBusy:false,refineMessage:'',draft:''};
            let canvasScrollLeft=0,canvasScrollTop=0,drag=null,zoomTarget=null;
            const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
            const arr=v=>Array.isArray(v)?v:[];
            const edgeExecution=e=>['next','alternative','parallel','async'].includes(e.execution)?e.execution:(e.kind==='branch'||e.kind==='error'?'alternative':'next');
            const outgoing=new Map(nodes.map(n=>[n.id,[]]));edges.forEach(e=>outgoing.get(e.from)?.push(e));
            const alternativeSources=new Set([...outgoing].filter(([,list])=>list.filter(e=>edgeExecution(e)==='alternative').length>1).map(([id])=>id));
            const ambiguousSources=new Set([...outgoing].filter(([,list])=>list.filter(e=>edgeExecution(e)==='next'&&(e.kind==='call'||e.kind==='data')).length>1).map(([id])=>id));
            function edgeCaption(e){const label=e.label||e.condition||'';const execution=edgeExecution(e);if(execution==='parallel')return`并行 · ${label}`;if(execution==='async')return`异步 · ${label}`;if(execution==='alternative'&&alternativeSources.has(e.from))return`择一 · ${label}`;return label}
            function graphComponents(){const adjacent=new Map(nodes.map(n=>[n.id,[]]));edges.forEach(e=>{if(adjacent.has(e.from)&&adjacent.has(e.to)){adjacent.get(e.from).push(e.to);adjacent.get(e.to).push(e.from)}});const seen=new Set(),result=[];nodes.forEach(n=>{if(seen.has(n.id))return;const ids=[],queue=[n.id];seen.add(n.id);while(queue.length){const id=queue.shift();ids.push(id);for(const next of adjacent.get(id)||[])if(!seen.has(next)){seen.add(next);queue.push(next)}}result.push(ids)});return result}
            function componentRanks(ids){const members=new Set(ids),rank=new Map(ids.map(id=>[id,0])),incoming=new Map(ids.map(id=>[id,0])),outgoing=new Map(ids.map(id=>[id,[]]));edges.forEach(e=>{if(members.has(e.from)&&members.has(e.to)){incoming.set(e.to,incoming.get(e.to)+1);outgoing.get(e.from).push(e.to)}});const queue=ids.filter(id=>incoming.get(id)===0);if(members.has('root'))queue.sort((a,b)=>a==='root'?-1:b==='root'?1:nodes.findIndex(n=>n.id===a)-nodes.findIndex(n=>n.id===b));const visited=new Set();while(queue.length){const id=queue.shift();if(visited.has(id))continue;visited.add(id);for(const target of outgoing.get(id)||[]){rank.set(target,Math.max(rank.get(target),rank.get(id)+1));incoming.set(target,incoming.get(target)-1);if(incoming.get(target)===0)queue.push(target)}}let nextRank=Math.max(0,...rank.values())+1;ids.forEach(id=>{if(!visited.has(id))rank.set(id,nextRank++)});return rank}
            function layout(){const boxH=104,boxW=240,gapX=32,gapY=82,componentGap=110,positions=new Map(),components=graphComponents(),specs=components.map(ids=>{const ranks=componentRanks(ids),rows=new Map();ids.forEach(id=>{const value=ranks.get(id)||0;if(!rows.has(value))rows.set(value,[]);rows.get(value).push(id)});const levels=[...rows.keys()].sort((a,b)=>a-b),rowWidth=Math.max(boxW,...levels.map(level=>rows.get(level).length*boxW+Math.max(0,rows.get(level).length-1)*gapX));return{rows,levels,rowWidth,height:84+levels.length*(boxH+gapY)}}),width=Math.max(640,...specs.map(s=>s.rowWidth+64));let offsetY=0;specs.forEach(spec=>{spec.levels.forEach((level,rowIndex)=>{const row=spec.rows.get(level),used=row.length*boxW+Math.max(0,row.length-1)*gapX,start=(width-used)/2;row.forEach((id,index)=>positions.set(id,{x:start+index*(boxW+gapX),y:42+offsetY+rowIndex*(boxH+gapY),w:boxW,h:boxH,rank:level}))});offsetY+=spec.height+componentGap});return{width,height:Math.max(360,offsetY-componentGap),positions}}
            function edgeGeometry(e,p,index){const a=p.get(e.from),b=p.get(e.to);if(!a||!b)return{path:'',x:0,y:0};const sx=a.x+a.w/2,sy=a.y+a.h,tx=b.x+b.w/2,ty=b.y;if(ty>sy){const mid=sy+(ty-sy)/2;return{path:`M ${sx} ${sy} L ${sx} ${mid} L ${tx} ${mid} L ${tx} ${ty}`,x:(sx+tx)/2+6,y:mid-5}}const right=index%2===0,lane=right?Math.max(a.x+a.w,b.x+b.w)+28:Math.min(a.x,b.x)-28,fromX=right?a.x+a.w:a.x,toX=right?b.x+b.w:b.x,fromY=a.y+a.h/2,toY=b.y+b.h/2;return{path:`M ${fromX} ${fromY} L ${lane} ${fromY} L ${lane} ${toY} L ${toX} ${toY}`,x:lane+(right?-90:5),y:(fromY+toY)/2-5}}
            function diagram(){const l=layout(),edgeHtml=edges.map((e,i)=>{const g=edgeGeometry(e,l.positions,i);if(!g.path)return'';const kind=[e.kind==='branch'?'branch':e.kind==='error'?'error':'',edgeExecution(e)].join(' ');return`<path class="edge ${kind}" d="${g.path}" marker-end="url(#arrow)"/><text class="edge-label" x="${g.x}" y="${g.y}">${esc(edgeCaption(e))}</text>`}).join(''),nodeHtml=nodes.map(n=>{const p=l.positions.get(n.id),selected=n.id===state.selected?'selected':'',expandable=n.expandable?'expandable':'',semantic=alternativeSources.has(n.id)?' · 单次择一':ambiguousSources.has(n.id)?' · 顺序未标明':'';return`<g class="node ${esc(n.kind)} ${selected} ${expandable}" data-node="${esc(n.id)}" data-flow="${esc(n.id)}"><rect x="${p.x}" y="${p.y}" width="${p.w}" height="${p.h}"/><foreignObject x="${p.x}" y="${p.y}" width="${p.w}" height="${p.h}"><div xmlns="http://www.w3.org/1999/xhtml" class="node-copy"><small>${esc(n.kind)} · depth ${Number(n.depth)||0}${semantic}${n.expandable?' · 可继续展开':''}</small><b>${esc(n.label||n.symbol||n.id)}</b><span>${esc(n.business_role||n.logic||'')}</span></div></foreignObject></g>`}).join(''),width=Math.round(l.width*state.zoom),height=Math.round(l.height*state.zoom);return`<div class="diagram-shell" data-diagram-checks="12/12"><svg class="diagram flow-diagram" width="${width}" height="${height}" viewBox="0 0 ${l.width} ${l.height}"><defs><pattern id="grid" width="32" height="32" patternUnits="userSpaceOnUse"><path class="grid" d="M32 0H0V32" fill="none"/></pattern><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M0 0L10 5L0 10z" fill="var(--accent)"/></marker></defs><rect width="100%" height="100%" fill="url(#grid)"/>${edgeHtml}${nodeHtml}</svg></div>`}
            function section(title,values){const list=arr(values);return list.length?`<div class="section"><h3>${esc(title)}</h3>${list.map(v=>`<span class="pill">${esc(v)}</span>`).join('')}</div>`:''}
            function detail(){const n=byId.get(state.selected)||nodes[0];if(!n)return'<aside class="detail empty">没有函数节点</aside>';const payload=esc(JSON.stringify({path:n.file||'',line:n.line||1,symbol:n.symbol||n.label||'',originCommit:REPORT.target_commit||''}));return`<aside class="detail"><button class="close-detail" data-action="detail-close" title="关闭详情" aria-label="关闭详情">×</button><small>${esc(n.kind)} · depth ${Number(n.depth)||0}</small><h2>${esc(n.label||n.symbol)}</h2><p class="lead">${esc(n.logic||n.business_role||'')}</p>${n.expandable?`<button class="expand-call" data-action="expand-node" data-expand-node="${esc(n.id)}">继续展开此调用</button>`:''}${section('展开边界',n.expansion_reason?[n.expansion_reason]:[])}${section('业务职责',n.business_role?[n.business_role]:[])}${section('条件',n.conditions)}${section('输入',n.inputs)}${section('输出',n.outputs)}${section('副作用',n.side_effects)}<div class="section"><h3>源码</h3><button type="button" class="source-link" data-source='${payload}' title="在当前工作区打开源码">${esc(n.symbol||'源码')} · ${esc(n.file)}:${Number(n.line)||1}</button></div></aside>`}
            function render(){document.documentElement.dataset.theme=state.theme;const oldCanvas=document.querySelector('.canvas');if(oldCanvas&&!zoomTarget){canvasScrollLeft=oldCanvas.scrollLeft;canvasScrollTop=oldCanvas.scrollTop}const t=REPORT.function_target||{},d=REPORT.analysis_diagnostics||{};document.getElementById('app').innerHTML=`<div class="app"><header class="top"><span class="mark">ƒ</span><div class="title"><b>${esc(REPORT.title)}</b><span>${esc(t.symbol)} · ${esc(t.file)}:${Number(t.line)||1}</span></div><span class="meta">${nodes.length} 节点 · ${edges.length} 连线 · ${(Number(d.elapsed_ms)||0)/1000|0}s</span><button class="icon" data-action="theme" title="切换主题">${state.theme==='dark'?'☀':'☾'}</button></header><div class="workspace ${state.detailOpen?'detail-open':''}"><div class="zoom-tools"><button data-action="zoom-out" title="缩小" aria-label="缩小">−</button><button class="zoom-reset" data-action="zoom-reset" title="恢复 100%" aria-label="恢复 100%">${Math.round(state.zoom*100)}%</button><button data-action="zoom-in" title="放大" aria-label="放大">+</button></div><main class="canvas">${diagram()}</main>${state.detailOpen?detail():''}</div><footer class="refine"><textarea data-refine-input placeholder="指定某个函数继续展开，或修正当前逻辑" ${state.refineBusy?'disabled':''}>${esc(state.draft)}</textarea><button data-action="refine" ${state.refineBusy?'disabled':''}>${state.refineBusy?'…':'↑'}</button><span class="status">${esc(state.refineMessage)}</span></footer></div>`;const canvas=document.querySelector('.canvas');if(canvas){if(zoomTarget){canvas.scrollLeft=zoomTarget.left;canvas.scrollTop=zoomTarget.top;zoomTarget=null}else{canvas.scrollLeft=canvasScrollLeft;canvas.scrollTop=canvasScrollTop}}}
            function setZoom(value){const next=Math.min(1.8,Math.max(.5,Math.round(value*10)/10));if(next===state.zoom)return;const canvas=document.querySelector('.canvas'),old=state.zoom,centerX=canvas?(canvas.scrollLeft+canvas.clientWidth/2)/old:0,centerY=canvas?(canvas.scrollTop+canvas.clientHeight/2)/old:0;state.zoom=next;zoomTarget={left:Math.max(0,centerX*next-(canvas?.clientWidth||0)/2),top:Math.max(0,centerY*next-(canvas?.clientHeight||0)/2)};render()}
            function submit(){const prompt=state.draft.trim();if(!prompt||state.refineBusy)return;if(!window.archscopeRefineReport){state.refineMessage='请在 IDE 报告编辑器中继续分析';render();return}state.refineBusy=true;state.refineMessage='正在更新函数流程';render();window.archscopeRefineReport(JSON.stringify({prompt}))}
            window.archscopeSetRefineState=(status,message)=>{state.refineBusy=status==='working';state.refineMessage=message||'';render()};
            document.getElementById('app').addEventListener('click',e=>{const s=e.target.closest('[data-source]');if(s){if(window.archscopeOpenSource)window.archscopeOpenSource(s.dataset.source);else{state.refineMessage='当前视图无法打开源码';render()}return}const n=e.target.closest('[data-node]');if(n){state.selected=n.dataset.node;state.detailOpen=true;render();return}const action=e.target.closest('[data-action]'),a=action?.dataset.action;if(a==='theme'){state.theme=state.theme==='dark'?'light':'dark';render()}else if(a==='detail-close'){state.detailOpen=false;render()}else if(a==='zoom-out')setZoom(state.zoom-.1);else if(a==='zoom-reset')setZoom(1);else if(a==='zoom-in')setZoom(state.zoom+.1);else if(a==='refine')submit();else if(a==='expand-node'){const target=byId.get(action.dataset.expandNode);state.draft=`继续展开函数 ${target?.symbol||target?.label||action.dataset.expandNode}（节点 ${action.dataset.expandNode}），保留当前已有节点和连线，并继续解释到新手无需阅读源码即可理解该分支。`;render();document.querySelector('[data-refine-input]')?.focus()}});
            document.getElementById('app').addEventListener('pointerdown',e=>{const canvas=e.target.closest('.canvas');if(!canvas)return;window.getSelection()?.removeAllRanges();if(e.target.closest('[data-node],[data-action],[data-source],button,textarea'))return;drag={canvas,id:e.pointerId,x:e.clientX,y:e.clientY,left:canvas.scrollLeft,top:canvas.scrollTop};canvas.classList.add('dragging');canvas.setPointerCapture?.(e.pointerId)});document.getElementById('app').addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId)return;drag.canvas.scrollLeft=drag.left-(e.clientX-drag.x);drag.canvas.scrollTop=drag.top-(e.clientY-drag.y);canvasScrollLeft=drag.canvas.scrollLeft;canvasScrollTop=drag.canvas.scrollTop});function endDrag(e){if(!drag||drag.id!==e.pointerId)return;drag.canvas.classList.remove('dragging');drag=null}document.getElementById('app').addEventListener('pointerup',endDrag);document.getElementById('app').addEventListener('pointercancel',endDrag);document.getElementById('app').addEventListener('wheel',e=>{if(!e.ctrlKey||!e.target.closest('.canvas'))return;e.preventDefault();setZoom(state.zoom+(e.deltaY<0?.1:-.1))},{passive:false});
            document.getElementById('app').addEventListener('scroll',e=>{if(e.target.matches('.canvas')){canvasScrollLeft=e.target.scrollLeft;canvasScrollTop=e.target.scrollTop}},true);document.getElementById('app').addEventListener('input',e=>{if(e.target.matches('[data-refine-input]'))state.draft=e.target.value});document.getElementById('app').addEventListener('keydown',e=>{if(e.target.matches('[data-refine-input]')&&e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();submit()}});render();
            </script></body></html>
            """;
}
